head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_list_sync = function() {
    var url = "/listingCommon.do?method=listGeneral" + "&outputMessageId=ELW_ISU_LISTED_HISTORY_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstproc.lstrcv.select.elw.listedhistory.condition" + "&{P}param01=" + $c.stf.getObjectValue(txb_ISU_CD);
    dts_List.DataID = encodeURI(url);
    dts_List.reset();
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
};
scwin.dts_IssList_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(0, panel_page);
    $c.cm.CloseWin(rowcount, grd_List);
};
scwin.btn_Excel_onclick = function() {
    $c.data.downloadGridViewExcel(grd_List, "상장내역", "", "8");
};
scwin.btn_Close_onclick = function() {
    self.close();
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_Top);
    var parentWin = $c.frame.path("../");
    //alert('[parentWin]'+parentWin);
    txb_ISU_CD.setValue(parentWin.txb_ISU_CD.getValue());
    txb_ISU_KOR_NM.setValue(parentWin.txb_ISU_KOR_NM.getValue());
    scwin.fn_list_sync();
};
